class Solution:
    def winner(self, names: List[str], scores: List[int]) -> str:
        tot = defaultdict(int)
        for nm, sc in zip(names, scores): tot[nm] += sc
        m = max(tot.values()); run = defaultdict(int)
        for nm, sc in zip(names, scores):
            run[nm] += sc
            if tot[nm] == m and run[nm] >= m: return nm

